INSERT INTO `outpatient_emr` VALUES (1,101578,100001,'D24001','1','1','1','1','1','1','2026-06-11 22:59:04','2026-06-11 23:15:25'),(2,109235,100003,'D24002','反复咳嗽3周，有白色粘痰','患者3周前受凉后出现咳嗽，初期干咳，近1周咳白色粘痰，伴咽痒，无发热。自行服用止咳糖浆效果不佳。','既往体健，否认药物过敏史。有吸烟史10年，每日1包。','T 36.5℃，咽部充血，双肺呼吸音粗，未闻及干湿啰音。','急性支气管炎','口服阿莫西林胶囊0.5g bid×7天，复方甘草口服液10ml tid×7天。建议戒烟。','2026-06-12 10:15:00',NULL),(3,109236,100004,'D24005','头晕伴胸闷1周','患者近1周出现阵发性头晕，伴胸闷气短，活动后加重。无恶心呕吐，无胸痛。','高血压病史5年，规律服用降压药。否认糖尿病。','BP 155/95mmHg，心率88次/分，心律齐，未闻及病理性杂音。','高血压病2级（中危）','调整降压方案，加用硝酸异山梨酯。建议监测24小时动态血压。','2026-06-12 11:05:00',NULL),(4,109237,100005,'D24010','右侧膝关节疼痛3个月','患者3个月前无明显诱因出现右膝关节疼痛，上下楼梯时加重，活动受限。曾贴敷膏药效果不佳。','既往有膝关节外伤史。否认风湿病史。','右膝关节轻度肿胀，压痛阳性，浮髌试验阴性，活动度屈曲100°。','右膝骨关节炎','口服布洛芬缓释胶囊0.3g bid，酮洛芬胶囊50mg bid。建议理疗科就诊。','2026-06-13 09:20:00',NULL),(5,109238,100006,'D24012','视力下降伴飞蚊症3个月','患者近3个月自觉视力渐进性下降，眼前有黑影飘动，伴视物模糊。无眼痛、无外伤。','近视病史15年。否认糖尿病、高血压。','VOD 0.3，VOS 0.4。双眼晶状体轻度混浊，玻璃体可见点状混浊。','双眼白内障初发期；玻璃体混浊','口服维生素C 0.2g qd。建议眼科门诊随访，必要时手术治疗。','2026-06-13 10:10:00',NULL),(6,109239,100007,'D24024','腰痛反复发作2年，加重1周','患者2年前开始出现腰痛，劳累后加重，休息后缓解。近1周因搬重物后疼痛明显加重，向臀部放射。','既往腰椎间盘突出症病史。否认外伤史。','腰椎生理曲度变直，L4-S1棘突间压痛阳性，直腿抬高试验左侧60°阳性，右侧70°。','腰椎间盘突出症（L4-L5、L5-S1）','口服复方丹参滴丸 10丸 tid。建议腰椎核磁共振检查，理疗科就诊。','2026-06-14 09:25:00',NULL),(7,109240,100008,'D24007','发热伴咽痛2天','患者2天前受凉后出现发热，体温最高39.2℃，伴咽痛、头痛、全身酸痛。','既往体健，否认药物过敏史。','T 38.8℃，咽部充血明显，双侧扁桃体II度肿大，可见脓点。双肺呼吸音清。','急性化脓性扁桃体炎','口服对乙酰氨基酚片0.5g prn退热，利巴韦林颗粒0.15g tid。建议休息3天。','2026-06-14 16:00:00',NULL),(8,109241,100009,'D24020','上腹部不适伴反酸1月','患者近1个月反复出现上腹部烧灼感，伴反酸、嗳气，饭后明显。偶有恶心，无呕吐、无黑便。','既往慢性胃炎病史。否认消化性溃疡病史。喜食辛辣食物。','腹部平软，上腹部轻压痛，无反跳痛。肠鸣音正常。','慢性胃炎（反流性食管炎可能）','口服奥美拉唑肠溶胶囊20mg qd×14天。建议胃镜检查，忌辛辣饮食。','2026-06-15 09:12:00',NULL),(9,109242,100010,'D24025','头晕伴视物旋转3天','患者3天前突发头晕，视物旋转，伴恶心呕吐，耳鸣。持续数分钟至数十分钟缓解。','既往有梅尼埃病史。否认高血压、糖尿病。','BP 120/80mmHg，眼震阳性，闭目难立征阳性。神经系统检查未见异常。','梅尼埃病（急性发作期）','口服复方丹参滴丸 10丸 tid。建议脑电图、CT检查，耳鼻喉科会诊。','2026-06-15 10:05:00',NULL),(10,109235,100003,'D24002','反复咳嗽3周，有白色粘痰','患者3周前受凉后出现咳嗽，初期干咳，近1周咳白色粘痰，伴咽痒，无发热。自行服用止咳糖浆效果不佳。','既往体健，否认药物过敏史。有吸烟史10年，每日1包。','T 36.5℃，咽部充血，双肺呼吸音粗，未闻及干湿啰音。','急性支气管炎','口服阿莫西林胶囊0.5g bid×7天，复方甘草口服液10ml tid×7天。建议戒烟。','2026-06-12 10:15:00',NULL),(11,109236,100004,'D24005','头晕伴胸闷1周','患者近1周出现阵发性头晕，伴胸闷气短，活动后加重。无恶心呕吐，无胸痛。','高血压病史5年，规律服用降压药。否认糖尿病。','BP 155/95mmHg，心率88次/分，心律齐，未闻及病理性杂音。','高血压病2级（中危）','调整降压方案，加用硝酸异山梨酯。建议监测24小时动态血压。','2026-06-12 11:05:00',NULL),(12,109237,100005,'D24010','右侧膝关节疼痛3个月','患者3个月前无明显诱因出现右膝关节疼痛，上下楼梯时加重，活动受限。曾贴敷膏药效果不佳。','既往有膝关节外伤史。否认风湿病史。','右膝关节轻度肿胀，压痛阳性，浮髌试验阴性，活动度屈曲100°。','右膝骨关节炎','口服布洛芬缓释胶囊0.3g bid，酮洛芬胶囊50mg bid。建议理疗科就诊。','2026-06-13 09:20:00',NULL),(13,109238,100006,'D24012','视力下降伴飞蚊症3个月','患者近3个月自觉视力渐进性下降，眼前有黑影飘动，伴视物模糊。无眼痛、无外伤。','近视病史15年。否认糖尿病、高血压。','VOD 0.3，VOS 0.4。双眼晶状体轻度混浊，玻璃体可见点状混浊。','双眼白内障初发期；玻璃体混浊','口服维生素C 0.2g qd。建议眼科门诊随访，必要时手术治疗。','2026-06-13 10:10:00',NULL),(14,109239,100007,'D24024','腰痛反复发作2年，加重1周','患者2年前开始出现腰痛，劳累后加重，休息后缓解。近1周因搬重物后疼痛明显加重，向臀部放射。','既往腰椎间盘突出症病史。否认外伤史。','腰椎生理曲度变直，L4-S1棘突间压痛阳性，直腿抬高试验左侧60°阳性，右侧70°。','腰椎间盘突出症（L4-L5、L5-S1）','口服复方丹参滴丸 10丸 tid。建议腰椎核磁共振检查，理疗科就诊。','2026-06-14 09:25:00',NULL),(15,109240,100008,'D24007','发热伴咽痛2天','患者2天前受凉后出现发热，体温最高39.2℃，伴咽痛、头痛、全身酸痛。','既往体健，否认药物过敏史。','T 38.8℃，咽部充血明显，双侧扁桃体II度肿大，可见脓点。双肺呼吸音清。','急性化脓性扁桃体炎','口服对乙酰氨基酚片0.5g prn退热，利巴韦林颗粒0.15g tid。建议休息3天。','2026-06-14 16:00:00',NULL),(16,109241,100009,'D24020','上腹部不适伴反酸1月','患者近1个月反复出现上腹部烧灼感，伴反酸、嗳气，饭后明显。偶有恶心，无呕吐、无黑便。','既往慢性胃炎病史。否认消化性溃疡病史。喜食辛辣食物。','腹部平软，上腹部轻压痛，无反跳痛。肠鸣音正常。','慢性胃炎（反流性食管炎可能）','口服奥美拉唑肠溶胶囊20mg qd×14天。建议胃镜检查，忌辛辣饮食。','2026-06-15 09:12:00',NULL),(17,109242,100010,'D24025','头晕伴视物旋转3天','患者3天前突发头晕，视物旋转，伴恶心呕吐，耳鸣。持续数分钟至数十分钟缓解。','既往有梅尼埃病史。否认高血压、糖尿病。','BP 120/80mmHg，眼震阳性，闭目难立征阳性。神经系统检查未见异常。','梅尼埃病（急性发作期）','口服复方丹参滴丸 10丸 tid。建议脑电图、CT检查，耳鼻喉科会诊。','2026-06-15 10:05:00',NULL),(18,109235,100003,'D24002','反复咳嗽3周，有白色粘痰','患者3周前受凉后出现咳嗽，初期干咳，近1周咳白色粘痰，伴咽痒，无发热。自行服用止咳糖浆效果不佳。','既往体健，否认药物过敏史。有吸烟史10年，每日1包。','T 36.5℃，咽部充血，双肺呼吸音粗，未闻及干湿啰音。','急性支气管炎','口服阿莫西林胶囊0.5g bid×7天，复方甘草口服液10ml tid×7天。建议戒烟。','2026-06-12 10:15:00',NULL),(19,109236,100004,'D24005','头晕伴胸闷1周','患者近1周出